def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True


def solve(x):
    if type(x) is not dict or set(x) != {"n"} or type(x["n"]) is not int:
        raise ValueError("expected just one integer field n")
    if not -16 <= x["n"] <= 10000:
        raise ValueError("integer outside the verified range")
    return is_prime(x["n"])
